def inverse_cdf_tdist(P, nu):
    if P == 0:
        return -np.inf
    if P == 1:
        return np.inf
    if nu == 1:
        # Cauchy distribution
        return np.tan(np.pi * (P - 0.5))
    if nu == 2:
        # Rayleigh distribution
        return np.sqrt(-2 * np.log(1 - P)) if P < 1 else np.inf
