import numpy as np

class GSLMatrix:
    def __init__(self, data, rows, cols):
        self.matrix = ctypes.c_double * (rows * cols)
        self.matrix = ctypes.addressof(self.matrix)
        self.rows = rows
        self.cols = cols

    def free(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so").gsl_matrix_free(self.matrix)

    def __del__(self):
        self.free()

    def to_numpy(self):
        data = (ctypes.c_double * (self.rows * self.cols))()
        for i in range(self.rows):
            for j in range(self.cols):
                data[i * self.cols + j] = ctypes.c_double(self.matrix[i * self.cols + j]).value
        return np.frombuffer(data, dtype=np.float64).reshape(self.rows, self.cols)

    @staticmethod
def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray):
        raise ValueError("Input must be a numpy array")
    if np_array.ndim != 2:
        raise ValueError("Input must be a 2D array")
    rows, cols = np_array.shape
    gsl_matrix = ctypes.c_double * (rows * cols)
    gsl_matrix = ctypes.addressof(gsl_matrix)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix[i * cols + j] = np_array[i, j]
    return GSLMatrix(gsl_matrix, rows, cols)

    @staticmethod
def gsl_matrix_to_numpy(gsl_matrix):
    if not isinstance(gsl_matrix, GSLMatrix):
        raise ValueError("Input must be a GSLMatrix object")
