import numpy as np
import ctypes
import os

def numpy_to_gsl_matrix_complex(np_array):
    size = np_array.shape[0]
    gsl_matrix = ctypes.pointer(ctypes.c_double * (size * size))()
    for i in range(size):
        for j in range(size):
            val = np_array[i, j].real
            gsl_matrix[i * size + j] = val
            val = np_array[i, j].imag
            gsl_matrix[i * size + j + size * size] = val
    return gsl_matrix


def gsl_vector_to_numpy(gsl_vector, size):
    result = np.zeros(size, dtype=np.complex128)
    for i in range(size):
        real = gsl_vector[i * 2]
        imag = gsl_vector[i * 2 + 1]
        result[i] = complex(real, imag)
    return result


def compute_eigenvalues(A, B):
    size = A.shape[0]

    # Load GSL libraries
    try:
        os.environ['LD_LIBRARY_PATH'] = '/usr/local/gsl/lib:' + os.environ.get('LD_LIBRARY_PATH', '')
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except Exception as e:
        raise RuntimeError("Failed to load GSL library: ") from e

    # Convert input matrices to GSL format
    try:
        gsl_A = numpy_to_gsl_matrix_complex(A)
        gsl_B = numpy_to_gsl_matrix_complex(B)
    except Exception as e:
        raise ValueError("Invalid input matrix: ") from e

    # Call GSL function
    try:
        gsl.gsl_eigen_genherm(size, gsl_A, gsl_B)
    except Exception as e:
        raise RuntimeError("Failed to compute eigenvalues: ") from e

    # Extract eigenvalues
    try:
        gsl_eigenvalues = gsl_vector_to_numpy(gsl_A, size)
    except Exception as e:
        raise RuntimeError("Failed to extract eigenvalues: ") from e

    return gsl_eigenvalues

