import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def to_gsl(self):
        gsl_matrix = ctypes.create_string_buffer(ctypes.sizeof(ctypes.c_double * self.rows * self.cols))
        ptr = ctypes.pointer(gsl_matrix)
        for i in range(self.rows):
            for j in range(self.cols):
                ctypes.memmove(ctypes.addressof(ptr.contents) + i * self.cols * ctypes.sizeof(ctypes.c_double) + j * ctypes.sizeof(ctypes.c_double), 
                                ctypes.pointer(ctypes.c_double(self.data[i][j])), 
                                1)
        return gsl_matrix

    def from_gsl(self, gsl_matrix):
        self.data = [[0.0 for _ in range(self.cols)] for _ in range(self.rows)]
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i][j] = ctypes.c_double(ctypes.cast(gsl_matrix, ctypes.POINTER(ctypes.c_double)).contents).value


def matrix_to_gsl(matrix):
    return GSLMatrix(matrix).to_gsl()

def gsl_matrix_to_numpy(gsl_matrix):
    matrix = [[0.0 for _ in range(gsl_matrix.cols)] for _ in range(gsl_matrix.rows)]
    for i in range(gsl_matrix.rows):
        for j in range(gsl_matrix.cols):
            matrix[i][j] = ctypes.c_double(ctypes.cast(gsl_matrix, ctypes.POINTER(ctypes.c_double)).contents).value
    return matrix

