class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.data = (ctypes.c_double * (self.rows * self.cols))()

    def free(self):
        self.data = None

    def to_numpy(self):
        return np.array([self.data[i*self.cols:(i+1)*self.cols] for i in range(self.rows)], dtype=np.float64)

    def list_to_ctypes_matrix(lst):
        mat = GSLMatrix(len(lst), len(lst[0]))
        for i in range(mat.rows):
            for j in range(mat.cols):
                mat.data[i*mat.cols + j] = lst[i][j]
        return mat


